export function bookStoreService(s,storeId,offerId){const st=storeById(storeId),offer=isServiceStore(st)&&serviceMenu(st).find(o=>o.id===offerId);if(!offer)throw Error('Service not found.');if(levelOf(s)<st.tier)throw Error('Unlock this mall before booking here.');if(s.mallId!==st.mallId)throw Error('Visit this branch before booking.');if(s.cash<offer.price)throw Error('Not enough game money for this booking.');canAct(s,2,0,{care:true});const n=(s.serviceSerial||0)+1;s.cash-=offer.price;advance(s,2);s.serviceSerial=n;const b={id:'service-'+n,store:storeId,offer:offerId,paid:offer.price,day:s.day,used:false,refunded:false};s.serviceBookings.push(b);return b;}
