export function useStoreService(s,id,storeId){const b=s.serviceBookings.find(b=>b.id===id),st=storeById(storeId),offer=st&&serviceMenu(st).find(o=>o.id===b?.offer);if(!b||b.store!==storeId||!offer||s.mallId!==st.mallId)throw Error('Visit the original branch for this booking.');if(b.used||b.refunded)throw Error('This booking has already been used or refunded.');canAct(s,offer.minutes,0,{care:true});advance(s,offer.minutes);s.energy=Math.min(100,s.energy+offer.recovery);b.used=true;s.metrics.activities++;progress(s,'activity','service:'+s.day+':'+storeId);const key='service:'+storeId+':'+s.day;if(!s.activityLog.some(v=>v.id===key)){s.activityLog.push({id:key,day:s.day,mallId:s.mallId});addXP(s,8);}if(b.offer==='package-help'){for(const item of carried(s))item.checked=true;}return offer;}
