export function stock(s,id,size){const key=`${s.day}:${id}:${size}`;if(key in s.stock)return s.stock[key];return 1+hash(key)%3;}
export function price(s,p){const base=Math.round(p.price*(hash(p.id+s.day)%11===0&&storeById(p.store).tier<5?.8:1));return s.coupon&&s.coupon.day===s.day&&s.coupon.store===p.store?Math.round(base*.9):base;}
export const remainingTime=s=>CLOSE-s.minutes;
export const queueMinutes=s=>s.minutes>=900&&s.minutes<1080?8:0;
export function canAct(s,minutes,energy=0,{care=false}={}){
 if(s.minutes+minutes>CLOSE)throw Error(`Not enough time before 8 PM. This takes ${minutes} minutes. Head home and come back tomorrow.`);
 if(!care&&s.hunger<=5)throw Error('You’re too hungry to keep shopping. Visit the food court for a snack or meal.');
 if(s.energy<energy)throw Error(`You need ${energy} stamina. Rest on a bench or eat at the food court.`);
}
function advance(s,minutes,cost=0){const low=s.hunger<25;s.minutes=Math.min(CLOSE,s.minutes+minutes);s.hunger=Math.max(0,s.hunger-minutes*.16);s.energy=Math.max(0,s.energy-minutes*(low?.12:.06)-cost);}
function act(s,minutes,energy){canAct(s,minutes,energy);advance(s,minutes,energy);}
export function tick(s,minutes=1){if(s.paused||s.minutes>=CLOSE)return;advance(s,Math.max(0,Math.min(5,minutes)));}
function addXP(s,n){const before=levelOf(s);s.xp+=n;const after=levelOf(s);if(!s.sandbox)for(let i=before+1;i<=after;i++)s.cash+=LEVELS[i].bonus*100;}
function progress(s,id,key){if(!s.daily[id].includes(key))s.daily[id].push(key);}
export function claimDaily(s,id){const q=QUESTS.find(q=>q.id===id);if(!q)throw Error('Goal not found.');if(dailyGoalProgress(s,id)<q.target)throw Error('Finish this goal first.');if(s.daily.claimed.includes(id))throw Error('Reward already collected.');s.daily.claimed.push(id);s.cash+=q.cash;addXP(s,q.xp);if(s.daily.claimed.length===QUESTS.length)s.metrics.dailySets++;return q;}
export function visit(s,id){if(!storeById(id))throw Error('Store not found.');act(s,5,3);if(!s.visits.includes(id)){s.visits.push(id);addXP(s,15);}if(!s.daily.visit.includes(id))s.relationships[id]=Math.min(5,(s.relationships[id]||0)+1);progress(s,'visit',id);communityStories.event(s,'visit',id);return true;}
export function inspect(s,id){const p=byId(id);if(!p)throw Error('Product not found.');act(s,3,2);if(!s.seen.includes(id)){s.seen.push(id);addXP(s,8);s.metrics.inspects++;}progress(s,'inspect',id);communityStories.event(s,'inspect',id);return true;}
export function compare(s,id){const p=byId(id);if(!p)throw Error('Product not found.');const matches=PRODUCTS.filter(q=>q.brand===p.brand&&q.name===p.name&&q.id!==id);if(!matches.length)throw Error('There is no matching product elsewhere in the mall.');act(s,4,1);const identity=p.brand+' · '+p.name;if(!s.compared.includes(identity)&&!s.compared.includes(p.name)){s.compared.push(identity);addXP(s,12);}return matches;}
export function idealSize(s,p){if(p.sizes.length===1)return p.sizes[0];const candidate=['shoes','sandals'].includes(p.type)?s.shoeSize:p.type==='pants'?s.waist:p.type==='belt'?'90 cm':p.type==='bracelet'?(p.sizes.includes('PM')?'PM':'M'):p.type==='ring'?(s.ringSize||'7'):s.size;if(p.sizes.includes(candidate))return candidate;const numeric=['pants','shoes','sandals','belt','ring'].includes(p.type)&&Number.isFinite(Number(candidate))?p.sizes.find(size=>Number.parseFloat(size)===Number(candidate)):null;return numeric||p.sizes[Math.floor(p.sizes.length/2)];}
export function fit(s,id,size){const p=byId(id);if(!p||!p.sizes.includes(size))throw Error('Choose an available size.');if(!canTry(p))throw Error('Use the product demo for this type of product.');if(stock(s,id,size)<=0)throw Error('That size is sold out.');act(s,10,7);const key=id+':'+size;if(!s.tried.includes(key)){s.tried.push(key);addXP(s,12);}const fits=size===idealSize(s,p);if(fits){progress(s,'try',id);s.metrics.fits++;}return {fits,text:p.sizes.length===1?'Easy to carry and comfortable to wear.':fits?'A comfortable fit. You can move freely.':'This fit feels off. Try your usual size: '+idealSize(s,p)+'.'};}
export function checkout(s,storeId,cart){
 const st=storeById(storeId);if(!st)throw Error('Store not found.');if(levelOf(s)<st.tier)throw Error(`Unlock Level ${st.tier+1}: ${LEVELS[st.tier].name} to buy here.`);
 if(!Array.isArray(cart))throw Error('Your bag is invalid.');if(carried(s).length+cart.length>8)throw Error('Your arms are full. Leave today’s purchases at guest services before buying more.');
 if(!cart.length)throw Error('Your shopping bag is empty.');if(cart.length>8)throw Error('Carry up to eight items at once.');
 const duration=8+cart.length*2+queueMinutes(s);canAct(s,duration,5);let total=0;const counts={};
 const lines=cart.map(item=>{const p=byId(item.id);if(!p||p.archived||p.store!==storeId)throw Error('Pay for each store’s items at its own checkout.');if(!p.sizes.includes(item.size))throw Error('Choose a valid size.');const key=p.id+':'+item.size;counts[key]=(counts[key]||0)+1;if(counts[key]>stock(s,p.id,item.size))throw Error(p.name+' is sold out in that size.');const paid=price(s,p),tax=Math.round(paid*TAX);total+=paid+tax;return {productId:p.id,size:item.size,price:paid,tax,total:paid+tax};});
 if(total>s.cash)throw Error(`You need ${money(total-s.cash)} more, including tax.`);
 s.cash-=total;advance(s,duration,5);s.lifetimeSpent+=total;const id=`D${s.day}-${s.orders.length+1}`;
 lines.forEach((line,i)=>{const p=byId(line.productId);s.stock[`${s.day}:${p.id}:${line.size}`]=stock(s,p.id,line.size)-1;s.totalSaved+=Math.max(0,p.retail-line.price);s.purchases.push({...line,id:id+'-'+i,orderId:id,store:storeId,day:s.day,returned:false,worn:false,tags:true});if(line.price<p.retail)s.metrics.discounts++;if(!s.seen.includes('bought:'+p.id)){s.seen.push('bought:'+p.id);addXP(s,30);}});
 if(s.coupon?.store===storeId&&s.coupon.day===s.day)s.coupon=null;
 const order={id,day:s.day,minutes:s.minutes,store:storeId,total,subtotal:lines.reduce((a,l)=>a+l.price,0),tax:lines.reduce((a,l)=>a+l.tax,0),items:lines.length};s.orders.unshift(order);progress(s,'buy',id);s.metrics.checkouts++;return order;
}
export function returnEligibility(s,item){const p=byId(item.productId),st=storeById(item.store);if(!p||!st)return {ok:false,reason:'Retired demo item'};if(item.delivered)return {ok:false,reason:item.deliveredTo?'Given to '+item.deliveredTo:'Delivered as a shopping request'};if(item.giftWrap)return {ok:false,reason:'Unwrap at guest services before returning'};if(item.checked)return {ok:false,reason:'Collect from guest services first'};if(item.returned)return {ok:false,reason:'Already refunded'};if(p.finalSale)return {ok:false,reason:'Final sale'};if(item.worn||!item.tags)return {ok:false,reason:'Used · tags or packaging removed'};const days=st.policy-(s.day-item.day);return days<0?{ok:false,reason:'Return period expired'}:{ok:true,reason:days===0?'Return today':days+' days to return'};}
export function returnItem(s,id,atStore){const item=s.purchases.find(p=>p.id===id);if(!item)throw Error('Receipt not found.');if(!storeById(atStore))throw Error('Store not found.');if(item.store!==atStore)throw Error('Return this to '+storeById(item.store).name+'.');const eligibility=returnEligibility(s,item);if(!eligibility.ok)throw Error(eligibility.reason);act(s,10,3);item.returned=true;s.cash+=item.total;s.stock[`${s.day}:${item.productId}:${item.size}`]=stock(s,item.productId,item.size)+1;s.totalSaved-=Math.max(0,byId(item.productId).retail-item.price);s.lifetimeSpent-=item.total;s.metrics.returns++;if(s.outfit===id)s.outfit=null;return item.total;}
export function wear(s,id){const wrapped=s.purchases.find(i=>i.id===id);if(wrapped?.giftWrap)throw Error('Unwrap this gift at guest services before wearing it.');const item=s.purchases.find(p=>p.id===id);if(!item||item.returned||item.delivered)throw Error('That item is not in your wardrobe.');if(item.checked)throw Error('Collect this purchase from guest services first.');const p=byId(item.productId);if(!canTry(p))throw Error('Use this product from your collection.');if(!item.worn)s.metrics.wears++;item.worn=true;item.tags=false;s.outfit=id;const slot=slotForProduct(p);if(slot)s.equipment[slot]=id;s.displayItems=s.displayItems.filter(v=>v!==id);return item;}
export function unequip(s,slot){if(!(slot in SLOT_NAMES))throw Error('Equipment slot not found.');delete s.equipment[slot];s.outfit=Object.values(s.equipment).at(-1)||null;}
export const equipped=s=>Object.values(s.equipment||{});
export function equippedLook(s){return Object.fromEntries(Object.entries(s.equipment||{}).flatMap(([slot,id])=>{const i=owned(s).find(i=>i.id===id&&!i.checked);return i?[[slot,byId(i.productId)]]:[];}));}
export function useProduct(s,id){const item=s.purchases.find(i=>i.id===id);if(!item||item.returned||item.delivered)throw Error('That purchase is no longer available.');if(item.checked)throw Error('Collect this purchase from guest services first.');const p=byId(item.productId);if(item.giftWrap)throw Error('Unwrap this gift at guest services before using it.');if(item.worn){if(canTry(p))return wear(s,id);return item;}if(['food','drink'].includes(p.type)){canAct(s,12,0,{care:true});advance(s,12);s.hunger=Math.min(100,s.hunger+(p.fullness??(p.type==='food'?40:8)));s.energy=Math.min(100,s.energy+(p.recovery??(p.type==='drink'?25:12)));if(p.type==='food'){s.metrics.meals++;progress(s,'eat',item.id);}else s.metrics.coffees++;item.worn=true;item.tags=false;return item;}act(s,p.type==='buildingtoy'?30:canTry(p)?3:10,p.type==='buildingtoy'?5:1);if(canTry(p))return wear(s,id);item.worn=true;item.tags=false;return item;}
export const mallOf=s=>mallById(s.mallId)||MALLS[0];
