export function travelMall(s,id){const m=mallById(id);if(!m)throw Error('Mall not found.');const rank=MALLS.indexOf(m);if(levelOf(s)<rank)throw Error(`Reach Level ${rank+1} · ${m.xp} XP to unlock ${m.name}.`);if(s.mallId===id)return m;canAct(s,20,0,{care:true});advance(s,20,2);s.mallId=id;s.mapPosition=null;s.floor=0;s.district=m.sections[0].id;s.mapOverview=false;s.avatar={u:4.4,v:4.1};s.metrics.travels++;if(!s.visitedMalls.includes(id)){s.visitedMalls.push(id);addXP(s,25);}return m;}
