export function eat(s,id){const food=[...FOOD,...COFFEE_MENU].find(f=>f.id===id);if(!food)throw Error('Meal not found.');if(s.cash<food.price)throw Error('Not enough game money. Free water and a bench are available.');canAct(s,food.minutes,0,{care:true});s.cash-=food.price;advance(s,food.minutes);s.hunger=Math.min(100,s.hunger+food.hunger);s.energy=Math.min(100,s.energy+food.energy);if(food.category==='coffee')s.metrics.coffees++;if(food.hunger>=10){s.metrics.meals++;progress(s,'eat',`${s.day}:${s.metrics.meals}`);}return food;}
