export function appointment(s){if(levelOf(s)<9)throw Error('Styling appointments unlock at Level 10.');if(s.appointmentDay===s.day)throw Error('You have already had a styling appointment today.');act(s,35,5);s.appointmentDay=s.day;s.metrics.appointments++;addXP(s,20);return true;}
export const canTry=p=>p?.audience!=='child'&&['shirt','hoodie','cardigan','jacket','shorts','pants','shoes','sandals','bag','crossbody','backpack','duffel','wallet','belt','digitalwatch','bracelet','scarf','hat','necklace','earrings','ring','watch','sunglasses'].includes(p.type);
export const categoryOf=p=>['food','drink'].includes(p.type)?'Food & drinks':['shirt','hoodie','cardigan','jacket','pants','shorts'].includes(p.type)?'Clothing':['shoes','sandals'].includes(p.type)?'Footwear':['bag','backpack','crossbody','duffel','wallet','belt','digitalwatch','bracelet','scarf','hat','necklace','earrings','ring','watch','sunglasses'].includes(p.type)?'Bags & accessories':['perfume','skincare','lipstick','makeup','mascara'].includes(p.type)?'Beauty':['earbuds','headphones','speaker','tracker','stylus','mouse','keyboard','charger','cable'].includes(p.type)?'Tech':'Hobbies & home';
export function demo(s,id){const p=byId(id);if(!p)throw Error('Product not found.');act(s,6,2);if(!s.demos.includes(id)){s.demos.push(id);s.metrics.demos++;addXP(s,10);}progress(s,'demo',id);return {text:p.type==='buildingtoy'?'You examine the real set model and try a short sample build.':categoryOf(p)==='Beauty'?'You explore a simulated tester and read the actual product identity. No real skin or fragrance recommendation is made.':'You try a simulated demonstration and check the real model before deciding.'};}
export function travel(s,district){if(!DISTRICTS.some(d=>d.id===district))throw Error('District not found.');if(s.district!==district){canAct(s,3,0,{care:true});advance(s,3,1);s.metrics.travels++;s.district=district;s.avatar={u:4.4,v:4.1};}s.mapOverview=false;return district;}
export function visitVenue(s,id){if(!VENUES.some(v=>v.id===id))throw Error('Location not found.');canAct(s,2,0,{care:true});advance(s,2,1);if(!s.venues.includes(id)){s.venues.push(id);addXP(s,8);}return true;}
export const currentPopup=s=>POPUPS[(s.day-1)%POPUPS.length];
export function claimPopup(s){const event=currentPopup(s);if(s.popupStamps.some(stamp=>stamp.day===s.day))throw Error('Today’s pavilion stamp is already in your passport.');act(s,10,2);s.popupStamps.push({day:s.day,event:event.id});s.metrics.popups++;s.coupon={day:s.day,store:event.store};addXP(s,20);progress(s,'popup',String(s.day));return event;}
export function takePhoto(s){if(s.cash<500)throw Error('The photo booth costs $5 in game money.');canAct(s,10,0,{care:true});s.cash-=500;advance(s,10,1);const fresh=!s.postcards.some(p=>p.district===s.district);s.postcards.push({day:s.day,district:s.district});s.metrics.photos++;communityStories.event(s,'photo','photo');if(fresh)addXP(s,15);return DISTRICTS.find(d=>d.id===s.district);}
