export const owned=s=>s.purchases.filter(p=>!p.returned&&!p.delivered);
export const carried=s=>owned(s).filter(p=>p.day===s.day&&!p.checked&&!equipped(s).includes(p.id)&&p.id!==s.outfit);
// Raw branch IDs remain on receipts, stock and map evidence. Story goals that
// name a retailer derive merchant progress without rewriting the saved records.
export const retailerKey=id=>merchantIdentity(storeById(id)?.name||'');
export const sameRetailer=(actual,target)=>!!retailerKey(actual)&&retailerKey(actual)===retailerKey(target);
export const visitedRetailer=(s,id)=>s.visits.some(actual=>sameRetailer(actual,id));
const modelIdentityCache=new WeakMap();
export function modelKey(p){if(!p||typeof p!=='object')return '';let key=modelIdentityCache.get(p);if(key===undefined){key=merchantIdentity(p.brand)+'|'+String(p.name).normalize('NFKC').trim().replace(/\s+/g,' ').toLocaleLowerCase('en-US');modelIdentityCache.set(p,key);}return key;}
export const sameModel=(a,b)=>!!a&&!!b&&modelKey(a)===modelKey(b);
export const modelCount=products=>new Set(products.filter(Boolean).map(modelKey)).size;
export const dailyGoalProgress=(s,id)=>['inspect','try','demo'].includes(id)?modelCount((s.daily[id]||[]).map(byId)):(s.daily[id]||[]).length;
const ownStore=(s,id)=>owned(s).filter(p=>sameRetailer(p.store,id));
const branchesByMerchant=new Map();for(const st of STORES){const key=retailerKey(st.id);if(!branchesByMerchant.has(key))branchesByMerchant.set(key,[]);branchesByMerchant.get(key).push(st);}
const storyMallStores=new Map(MALLS.map(m=>[m.id,new Set(m.sections.flatMap(d=>d.stores))]));
const modelsByIdentity=new Map();for(const p of PRODUCTS){const key=modelKey(p);if(!modelsByIdentity.has(key))modelsByIdentity.set(key,[]);modelsByIdentity.get(key).push(p);}
function storyBranchOrder(s,a,b){const here=storyMallStores.get(s.mallId),ah=here?.has(a.id),bh=here?.has(b.id);return Number(bh)-Number(ah)||(ah&&bh?Number(storeFloor(mallOf(s),b.id)===(s.floor||0))-Number(storeFloor(mallOf(s),a.id)===(s.floor||0)):0)||a.tier-b.tier||a.id.localeCompare(b.id);}
export function preferredStoryStore(s,id){const st=storeById(id);if(!st)return 'ross';const choices=(branchesByMerchant.get(retailerKey(id))||[st]).filter(v=>v.tier<=levelOf(s));return choices.sort((a,b)=>storyBranchOrder(s,a,b))[0]?.id||id;}
export function preferredStoryProduct(s,id){const p=byId(id);if(!p)return null;const all=modelsByIdentity.get(modelKey(p))||[],unlocked=all.filter(v=>storeById(v.store).tier<=levelOf(s));return [...(unlocked.length?unlocked:all)].sort((a,b)=>storyBranchOrder(s,storeById(a.store),storeById(b.store))||price(s,a)-price(s,b))[0]||null;}
export const errandMatchesProduct=(p,brief)=>!!p&&(!brief.types||brief.types.includes(p.type))&&(!brief.stores||brief.stores.some(id=>sameRetailer(p.store,id)));

