export const activeMission=s=>MISSIONS.find(m=>!s.missions.includes(m.id));
export const missionReady=(s,m)=>!!m&&m.steps.every(([,check])=>check(s));
export function claimMission(s,id){const m=activeMission(s);if(!m||m.id!==id)throw Error('Complete story chapters in order.');if(!missionReady(s,m))throw Error('Finish every step to claim this chapter.');s.missions.push(id);s.cash+=m.reward;addXP(s,m.xp);return m;}
