export function claimCollection(s,id){const c=collectionSets(s).find(c=>c.id===id);if(!c)throw Error('Collection not found.');if(c.claimed)throw Error('Collection reward already collected.');if(!c.ready)throw Error('Complete this collection first.');s.collectionRewards.push(id);s.cash+=c.cash;addXP(s,c.xp);return c;}
export function experienceSpec(s,id){const a=ACTIVITIES.find(a=>a.id===id);if(!a)throw Error('Activity not found.');return {...a,flower:FLOWER_BRIEFS[(s.day-1)%FLOWER_BRIEFS.length],tea:TEA_RECIPES[(s.day-1)%TEA_RECIPES.length],film:CINEMA_SHORTS[(s.day-1)%CINEMA_SHORTS.length],art:['circle','cube','arch'].map((_,i,arr)=>arr[(i+s.day-1)%3]),garden:['fountain','tree','bridge'],completed:s.activityLog.some(v=>v.day===s.day&&v.id===id)};}
export function completeExperience(s,id,choice){const spec=experienceSpec(s,id);let title='',valid=false;const same=(a,b)=>Array.isArray(a)&&a.length===b.length&&a.every((x,i)=>x===b[i]);if(id==='flowers'){valid=Array.isArray(choice?.stems)&&same([...choice.stems].sort(),[...spec.flower.recipe].sort());title=spec.flower.name;}else if(id==='tea'){valid=choice?.base===spec.tea.base&&choice?.temperature===spec.tea.temperature&&choice?.minutes===spec.tea.minutes;title=spec.tea.name;}else if(id==='artwalk'){valid=same(choice?.order,spec.art);title='Curator’s eye · '+spec.art.join(', ');}else if(id==='bridge'){valid=same([...(choice?.details||[])].sort(),[...spec.garden].sort());title='A garden observation';}else if(id==='cinema'){valid=choice?.film===spec.film.id&&Number.isInteger(choice?.seat)&&choice.seat>=1&&choice.seat<=6&&same(choice?.scenes,[0,1,2]);title=spec.film.title+' · seat '+choice?.seat;}else if(id==='carousel'){valid=Number.isInteger(choice?.horse)&&choice.horse>=0&&choice.horse<6;title='Carousel horse '+(choice?.horse+1);}if(!valid)throw Error('Take another look at the activity brief. You can change your choices and try again.');const result=enjoyActivity(s,id);const memory={id:s.day+':'+id,day:s.day,mallId:s.mallId,activity:id,title,choice:JSON.parse(JSON.stringify(choice))};s.activityMemories.push(memory);s.activityMemories=s.activityMemories.slice(-100);return {...result,memory};}
export function createPortrait(s,frame,pose){if(!Object.prototype.hasOwnProperty.call(PHOTO_FRAMES,frame)||!PHOTO_POSES.includes(pose))throw Error('Choose an available frame and pose.');if(s.photoAlbum.length>=20)throw Error('Your album holds twenty portraits. Download and remove one to make room.');takePhoto(s);const photo={id:'portrait-'+s.day+'-'+s.postcards.length,day:s.day,mallId:s.mallId,district:s.district,frame,pose,appearance:{...s.appearance},equipment:Object.fromEntries(Object.entries(equippedLook(s)).map(([slot,p])=>[slot,p.id])),name:s.playerName};s.photoAlbum.push(photo);return photo;}
export function removePortrait(s,id){s.photoAlbum=s.photoAlbum.filter(p=>p.id!==id);}
export function returnReminders(s){return owned(s).flatMap(i=>{const e=returnEligibility(s,i),days=storeById(i.store).policy-(s.day-i.day);return e.ok&&days<=3?[{item:i,product:byId(i.productId),days}]:[];}).sort((a,b)=>a.days-b.days);}
export function nextShoppingAction(s){const m=activeMission(s),chapter=m?.chapter||'✓',step=m?.steps.findIndex(([,check])=>!check(s))??0,base={chapter,title:m?.title||'A life well shopped',step:Math.max(0,step),steps:m?.steps.length||0};if(s.minutes>=CLOSE-11)return {...base,kind:'sleep',label:s.minutes>=CLOSE?'The mall is closed · walk home':'Closing soon · finish your day'};if(s.hunger<20)return {...base,kind:'venue',id:'food',label:'Take a meal break before shopping'};if(s.energy<15)return {...base,kind:'venue',id:'rest',label:'Rest on a bench before shopping'};const localAction=communityStories.next(s);if(localAction)return localAction;const outingAction=outingPlanner.next(s);if(outingAction)return outingAction;if(missionReady(s,m))return {...base,kind:'claim',id:m.id,label:'Collect your chapter reward'};const shop=(id,label)=>({...base,kind:'shop',id:preferredStoryStore(s,id),label:label||'Visit '+storeById(id).name}),venue=id=>({...base,kind:'venue',id,label:'Visit '+VENUES.find(v=>v.id===id).name}),page=(id,label)=>({...base,kind:'view',id,label}),missing=ids=>ids.find(id=>!visitedRetailer(s,id))||ids[0];if(!m)return page('collections','Explore your collection room and new styling briefs');const map={
 first:[()=>shop('ross','Enter Ross · inspect a real product'),()=>shop('ross','Try a product in your usual size'),()=>shop('ross','Choose a find and visit the checkout')],detective:[()=>shop(missing(['ross','marshalls'])),()=>({...base,kind:'product',id:PRODUCTS.find(p=>storeById(p.store).tier===0&&PRODUCTS.some(q=>q.id!==p.id&&q.brand===p.brand&&q.name===p.name))?.id,label:'Compare the same real product at different stores'}),()=>shop('ross','Look for an off-price find')],care:[()=>venue('food'),()=>venue('rest'),()=>({...base,kind:'sleep',label:'Walk home and welcome a new day'})],essentials:[()=>shop('uniqlo'),()=>({...base,kind:'product',id:'u-bag',label:'Look at the Round Mini Shoulder Bag'}),()=>page('wardrobe','Equip a kept purchase')],street:[()=>shop(missing(['hm','oldnavy','levis'])),()=>shop('levis'),()=>page('catalog','Discover a few more real product labels')],active:[()=>page('malls','Visit your destination passport'),()=>shop(missing(['nike','adidas'])),()=>shop('nike')],weekend:[()=>shop('lego'),()=>shop('lego'),()=>venue('popup')],lifestyle:[()=>shop('apple'),()=>shop('sephora'),()=>venue('coffee')],signature:[()=>page('malls','Visit your destination passport'),()=>shop('nordstrom'),()=>({...base,kind:'sleep',label:'Finish the day fed and rested'})],designer:[()=>shop(missing(['coach','longchamp','tory'])),()=>shop('longchamp'),()=>page('catalog','Find matching models to compare')],luxury:[()=>page('malls','Unlock and visit Beverly Center'),()=>shop('lv'),()=>shop('lv')],houses:[()=>shop(missing(['gucci','prada'])),()=>shop(missing(['gucci','prada'])),()=>shop('gucci')],orange:[()=>page('malls','Unlock South Coast Plaza'),()=>shop('hermes'),()=>shop('hermes')],home:[()=>page('wardrobe','Browse the brands in your collection'),()=>page('catalog','Compare matching real products'),()=>({...base,kind:'sleep',label:'Plan a fed-and-rested finish'})],passport:[()=>shop(CORE_STORES.find(st=>!visitedRetailer(s,st.id))?.id||'ross'),()=>venue('popup'),()=>venue('photo')],collection:[()=>page('collections','Discover your next collection goal'),()=>page('catalog','Read a new product label'),()=>page('missions','Complete and collect today’s daily goals')], 'garden-life':[()=>shop(missing(['newbalance','lululemon','alo'])),()=>venue(s.activityLog.some(a=>a.id==='bridge')?'carousel':'bridge'),()=>shop('alo')],'small-pleasures':[()=>shop('muji'),()=>shop('bathbody'),()=>venue('flowers')],'friendly-favors':[()=>page('journal','Accept a community shopping request'),()=>page('journal','Help with a new request brief'),()=>venue('services')],'week-rhythm':[()=>page('journal','Join today’s calendar activity'),()=>venue(ACTIVITIES.find(a=>!s.activityLog.some(v=>v.id===a.id))?.venue||'bridge'),()=>({...base,kind:'sleep',label:'Welcome another morning'})],'maison-tour':[()=>shop(CORE_STORES.find(st=>st.district==='terrace'&&!visitedRetailer(s,st.id))?.id||'dior'),()=>shop('dior'),()=>shop('tiffany')],celebrate:[()=>shop('tiffany'),()=>venue('art'),()=>shop('hermes')],'considered-collection':[()=>page('collections','Add something considered to your collection'),()=>page('catalog','Explore another real brand'),()=>page('catalog','Read another product label')],'galleria-life':[()=>page('malls','Finish your destination passport'),()=>page('journal','Help with another community request'),()=>page('journal','Join today’s calendar event')]};const action=(map[m.id]?.[Math.max(0,step)]||(()=>page('missions','Review your current chapter')))();if(action.kind==='product'){const p=preferredStoryProduct(s,action.id);if(p)action.id=p.id;}return action;}
function normalizeLife(s){s.serviceSerial=Number.isSafeInteger(s.serviceSerial)&&s.serviceSerial>=0?s.serviceSerial:0;s.serviceBookings=Array.isArray(s.serviceBookings)?s.serviceBookings.filter(b=>b&&typeof b.id==='string'&&isServiceStore(storeById(b.store))&&serviceMenu(storeById(b.store)).some(o=>o.id===b.offer)&&Number.isSafeInteger(b.paid)&&b.paid>=0&&Number.isInteger(b.day)&&b.day>0).slice(-1000).map(b=>({...b,used:!!b.used,refunded:!!b.refunded})):[];s.v9Welcome=s.v9Welcome===true;for(const key of ['serviceBookings','bondDays','topicLog','friendshipClaims','looks','styleEntries','displayItems','activityMemories','photoAlbum','collectionRewards'])if(!Array.isArray(s[key]))s[key]=[];s.friendships=Object.fromEntries(LOCALS.map(n=>[n.id,Math.min(10,Math.max(0,Number(s.friendships?.[n.id])||0))]));for(const key of ['bondDays','topicLog','friendshipClaims','collectionRewards'])s[key]=[...new Set(s[key].filter(x=>typeof x==='string'))].slice(-1000);s.lookSerial=Number.isSafeInteger(s.lookSerial)&&s.lookSerial>=0?s.lookSerial:0;s.looks=s.looks.filter(l=>l&&typeof l.id==='string'&&l.equipment&&typeof l.equipment==='object').slice(0,6).map(l=>({...l,name:cleanLabel(l.name)||'Saved look',equipment:Object.fromEntries(Object.entries(l.equipment).filter(([slot,id])=>SLOT_NAMES[slot]&&typeof id==='string')),appearance:normalizeAppearance(l.appearance,s.appearance)}));s.lookSerial=Math.max(s.lookSerial,...s.looks.map(l=>Number(l.id.split('-').at(-1))||0));s.styleEntries=s.styleEntries.filter(e=>e&&Number.isInteger(e.day)&&STYLE_BRIEFS.some(b=>b.id===e.brief)&&Array.isArray(e.products)).slice(-300);s.displayItems=[...new Set(s.displayItems.filter(id=>owned(s).some(i=>i.id===id&&i.worn)&&!Object.values(s.equipment).includes(id)))].slice(0,6);s.activityMemories=s.activityMemories.filter(m=>m&&ACTIVITIES.some(a=>a.id===m.activity)&&typeof m.title==='string'&&m.choice&&typeof m.choice==='object'&&(m.activity!=='flowers'||Array.isArray(m.choice.stems)&&m.choice.stems.every(id=>FLOWER_STEMS.some(f=>f.id===id)))).slice(-100);s.photoAlbum=s.photoAlbum.filter(p=>p&&typeof p.id==='string'&&Object.prototype.hasOwnProperty.call(PHOTO_FRAMES,p.frame)&&PHOTO_POSES.includes(p.pose)&&p.appearance&&p.equipment).slice(0,20).map(p=>({...p,name:cleanLabel(p.name,20)||'Shopper',equipment:Object.fromEntries(Object.entries(p.equipment).filter(([slot,id])=>SLOT_NAMES[slot]&&byId(id)))}));if(!byId(s.savingsTarget))s.savingsTarget=null;outingPlanner.normalize(s);commonsLife.normalize(s);normalizeAmenities(s);homeLife.normalize(s);neighborhoodLife.normalize(s);communityStories.normalize(s);companionLife.normalize(s);if(s.communityFocus)s.outingFocus=false;}

export function openAndDisplay(s,id){const item=owned(s).find(i=>i.id===id);if(!item||item.checked)throw Error('Collect this purchase before opening it.');if(s.displayItems.includes(id))return false;if(s.displayItems.length>=6)throw Error('Your shelf is full. Put something away first.');const before={...s.equipment};useProduct(s,id);pinDisplay(s,id);s.equipment=Object.fromEntries(Object.entries(before).filter(([,equippedId])=>equippedId!==id));s.outfit=Object.values(s.equipment).at(-1)||null;return true;}

// Unpaid bags survive a refresh only within the same shopping day and mall.
export function savedBags(s){const data=s.shoppingBags;if(!data||data.day!==s.day||data.mallId!==s.mallId||!data.bags||typeof data.bags!=='object')return {};const result={},counts=new Map();let room=Math.max(0,8-carried(s).length);for(const st of STORES){if(levelOf(s)<st.tier||!Array.isArray(data.bags[st.id]))continue;const items=[];for(const item of data.bags[st.id]){const p=byId(item?.id);if(!room||!p||p.archived||p.store!==st.id||!p.sizes.includes(item.size))continue;const key=p.id+':'+item.size,n=counts.get(key)||0;if(n>=stock(s,p.id,item.size))continue;items.push({id:p.id,size:item.size});counts.set(key,n+1);room--;}if(items.length)result[st.id]=items;}return result;}

export function rememberBags(s,bags){const previous=s.shoppingBags,same=!previous||previous.day===s.day&&previous.mallId===s.mallId;s.shoppingBags={day:s.day,mallId:s.mallId,bags:same?bags:{}};return s.shoppingBags.bags;}

const outingPlanner=createOutingPlanner({products:PRODUCTS,malls:MALLS,byId,storeById,levelOf,price,stock,idealSize,canTry,slotForProduct,modelKey,hash,tax:TAX,open:OPEN,close:CLOSE});
export const outingOffers=s=>outingPlanner.offers(s);
export const outingStatus=s=>outingPlanner.status(s);
export function acceptOuting(s,id){const o=outingPlanner.accept(s,id);s.communityFocus=null;return o;}
export const cancelOuting=s=>outingPlanner.cancel(s);
export function focusOuting(s,active=true){const current=outingStatus(s);if(active&&(!current||current.claimed))throw Error('Choose an unfinished outing first.');s.outingFocus=!!active;if(active)s.communityFocus=null;}
export function claimOuting(s){const reward=outingPlanner.claim(s);s.cash+=reward.cash;addXP(s,reward.xp);return reward;}


// Guest-service interactions are simulated services, not invented merchandise.
export const GIFT_WRAPS=[{id:'sage',name:'Sage paper',color:'#728c76'},{id:'rose',name:'Rose paper',color:'#b77e89'},{id:'midnight',name:'Midnight paper',color:'#405d71'}];
export function wrappablePurchases(s){return owned(s).filter(i=>!i.worn&&!i.checked&&i.tags&&!i.giftWrap&&!['food','drink'].includes(byId(i.productId).type));}
export function wrapGift(s,id,style){const item=wrappablePurchases(s).find(i=>i.id===id);if(!item)throw Error('Choose an unused purchase with its tags or packaging intact. Collect checked packages first.');if(!GIFT_WRAPS.some(w=>w.id===style))throw Error('Choose an available wrapping paper.');if(s.cash<200)throw Error('Gift wrapping costs $2 in game money.');canAct(s,6,0,{care:true});advance(s,6);s.cash-=200;item.giftWrap={style,day:s.day,fee:200};return item;}
export function unwrapGift(s,id){const item=owned(s).find(i=>i.id===id&&!i.checked&&i.giftWrap);if(!item)throw Error('Collect a wrapped purchase first.');canAct(s,1,0,{care:true});advance(s,1);delete item.giftWrap;return item;}
export function useAmenity(s,id){if(!['water','directory'].includes(id))throw Error('Amenity not found.');const last=s.amenityUses.slice().reverse().find(v=>v.id===id&&v.mallId===s.mallId&&v.day===s.day);if(id==='water'&&last&&s.minutes-last.minutes<30)throw Error('You just had water. Come back in '+Math.ceil(30-(s.minutes-last.minutes))+' game minutes.');canAct(s,3,0,{care:true});advance(s,3);if(id==='water')s.energy=Math.min(100,s.energy+8);s.amenityUses.push({id,day:s.day,minutes:s.minutes,mallId:s.mallId});s.amenityUses=s.amenityUses.slice(-90);communityStories.event(s,'amenity',id);return id;}
function normalizeAmenities(s){s.amenityUses=(Array.isArray(s.amenityUses)?s.amenityUses:[]).filter(v=>v&&['water','directory'].includes(v.id)&&Number.isSafeInteger(v.day)&&v.day>0&&v.day<=s.day&&Number.isFinite(v.minutes)&&v.minutes>=OPEN&&v.minutes<=CLOSE&&mallById(v.mallId)).slice(-90).map(v=>({id:v.id,day:v.day,minutes:v.minutes,mallId:v.mallId}));for(const i of s.purchases){if(i.deliveredTo!=='Maya')delete i.deliveredTo;const w=i.giftWrap;if(w&&GIFT_WRAPS.some(v=>v.id===w.style)&&Number.isSafeInteger(w.day)&&w.day>=i.day&&w.day<=s.day&&!i.worn&&!i.returned&&!['food','drink'].includes(byId(i.productId).type))i.giftWrap={style:w.style,day:w.day,fee:200};else delete i.giftWrap;}}
const communityStories=createCommunityStories({byId,modelKey,canTry,idealSize,mallById,canAct,advance});
export const localStories=s=>communityStories.all(s);
export const localStory=(s,id)=>communityStories.status(s,id);
export const beginLocalStory=(s,id,choice)=>communityStories.start(s,id,choice);
export const localGiftCandidates=s=>communityStories.giftCandidates(s);
export function trackLocalStory(s,id){if(!localStory(s,id)?.active)throw Error('Begin a local chapter first.');s.communityFocus=id;s.outingFocus=false;}
export function claimLocalChapter(s,id,giftId){const reward=communityStories.claim(s,id,giftId);s.cash+=reward.cash+reward.reimbursement;addXP(s,reward.xp);return reward;}

const homeLife=createHomeLife({byId,owned,slotForProduct,idealSize,mallById,canAct,advance,addXP,event:(...args)=>communityStories.event(...args)});
export const prepareTomorrow=s=>homeLife.prepare(s);
export const applyPreparedOutfit=s=>homeLife.apply(s);
export const signGuestbook=(s,mood,highlight)=>homeLife.guestbook(s,mood,highlight);
export function setRoomStyle(s,id){if(!ROOM_STYLES.some(v=>v.id===id))throw Error('Choose a room finish.');s.roomStyle=id;}

const neighborhoodLife=createNeighborhoodLife({mallById,canAct,advance,addXP,event:(...args)=>communityStories.event(...args)});
