export const recordCommons=(s,kind,choice,floor)=>commonsLife.record(s,kind,choice,floor);

export function toggleSavedShop(s,id){if(!storeById(id))throw Error('Choose an existing shop.');const list=s.savedShops||[];if(list.includes(id)){s.savedShops=list.filter(v=>v!==id);return false;}if(list.length>=80)throw Error('Your saved list has 80 shops. Remove one before adding another.');s.savedShops=[...list,id];return true;}
